import 'dart:math' as math;
import 'package:flutter/material.dart';
class NutritionRing extends StatelessWidget { const NutritionRing({super.key,required this.label,required this.value,required this.goal,required this.unit,required this.color}); final String label,unit; final double value,goal; final Color color; @override Widget build(BuildContext c){final progress=goal<=0?0:(value/goal).clamp(0,1).toDouble(); return SizedBox(width:92,height:122,child:Column(children:[TweenAnimationBuilder<double>(tween:Tween(begin:0,end:progress),duration:const Duration(milliseconds:700),curve:Curves.easeOutCubic,builder:(_,v,__)=>(SizedBox(width:78,height:78,child:CustomPaint(painter:_RingPainter(progress:v,color:color),child:Center(child:Text('${value.round()}\n/${goal.round()}$unit',textAlign:TextAlign.center,style:const TextStyle(fontSize:12,fontWeight:FontWeight.w600))))))),const SizedBox(height:6),Text(label,overflow:TextOverflow.ellipsis)]));}}
class _RingPainter extends CustomPainter { _RingPainter({required this.progress,required this.color}); final double progress; final Color color; @override void paint(Canvas canvas,Size size){final center=Offset(size.width/2,size.height/2);final radius=size.width/2-7;final base=Paint()..color=color.withValues(alpha:.18)..style=PaintingStyle.stroke..strokeWidth=8;final active=Paint()..color=color..style=PaintingStyle.stroke..strokeCap=StrokeCap.round..strokeWidth=8;canvas.drawCircle(center,radius,base);canvas.drawArc(Rect.fromCircle(center:center,radius:radius),-math.pi/2,math.pi*2*progress,false,active);} @override bool shouldRepaint(covariant _RingPainter old)=>old.progress!=progress||old.color!=color;}
